#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[]) {
    // Buffer size matches the original binary's limits (1024 bytes).
    char main_out[1024];
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *mode = argv[1];
    const char *input = argv[2];

    if (strcmp(mode, "to_camel") == 0) {
        // Convert snake_case to camelCase.
        size_t out_idx = 0;
        int capitalize = 0; // set after an underscore.
        for (size_t i = 0; input[i] && out_idx < sizeof(main_out) - 1; ++i) {
            char c = input[i];
            if (c == '_') {
                capitalize = 1; // next alphabetic character will be upper case.
                continue;
            }
            if (capitalize && c >= 'a' && c <= 'z') {
                c = (char)(c - 'a' + 'A');
            }
            main_out[out_idx++] = c;
            capitalize = 0;
        }
        main_out[out_idx] = '\0';
        puts(main_out);
    } else if (strcmp(mode, "to_snake") == 0) {
        // Convert camelCase to snake_case.
        size_t out_idx = 0;
        for (size_t i = 0; input[i] && out_idx < sizeof(main_out) - 1; ++i) {
            char c = input[i];
            if (c >= 'A' && c <= 'Z') {
                // Insert underscore before uppercase letters (except at the start).
                if (i != 0) {
                    main_out[out_idx++] = '_';
                }
                c = (char)(c - 'A' + 'a');
            }
            main_out[out_idx++] = c;
        }
        main_out[out_idx] = '\0';
        puts(main_out);
    } else {
        puts("INVALID_MODE");
    }
    return 0;
}
